// "Lo atiendo" button (callback_data 'claim:<id>') pressed in the staff group. Anything else is ignored.
const q = $input.first().json.callback_query || {};
const m = String(q.data || '').match(/^claim:(\d+)$/);
if (!m || !q.message) return [];
const f = q.from || {};
const name = [f.first_name, f.last_name].filter(Boolean).join(' ') || (f.username ? '@' + f.username : 'Equipo');
return [{ json: { case_id: Number(m[1]), staff_name: name, staff_tg_id: f.id, chat_id: q.message.chat.id,
  message_id: q.message.message_id, original_text: q.message.text || '', query_id: q.id } }];
